typedef long long ll;
typedef pair<int,int> pii;

int dx[]={1,-1,0,0};
int dy[]={0,0,1,-1};

struct Edge {
    int v, u;
    long long cap, flow=0;
    Edge(int v, int u, long long cap): v(v), u(u), cap(cap) {}
};

struct Network {
    vector<Edge> edges;
    vector<vector<int>> adj;
    int n, m=0, s, t;
    vector<int> level, ptr;
    queue<int> q;

    Network(int n, int s, int t): n(n), s(s), t(t) {
        adj.resize(n);
        level.resize(n);
        ptr.resize(n);
    }

    void add_edge(int v, int u, long long cap) {
        edges.emplace_back(v, u, cap);
        edges.emplace_back(u, v, 0);
        adj[v].push_back(m);
        adj[u].push_back(m+1);
        m+=2;
    }

    bool bfs() {
        while(!q.empty()) q.pop();
        fill(level.begin(), level.end(), -1);
        level[s]=0;
        q.push(s);
        while(!q.empty()) {
            int v=q.front(); q.pop();
            for (int id: adj[v]) {
                if (edges[id].cap - edges[id].flow <1) continue;
                if (level[edges[id].u]!=-1) continue;
                level[edges[id].u]=level[v]+1;
                q.push(edges[id].u);
            }
        }
        return level[t]!=-1;
    }

    long long augment(int v, long long flow_in) {
        if (v==t) return flow_in;
        for (int& cid=ptr[v]; cid<(int)adj[v].size(); cid++) {
            int id=adj[v][cid];
            int u=edges[id].u;
            if (level[v]+1!=level[u] || edges[id].cap - edges[id].flow<1) continue;
            long long pushed=augment(u, min(flow_in, edges[id].cap - edges[id].flow));
            if (pushed>0) {
                edges[id].flow+=pushed;
                edges[id^1].flow-=pushed;
                return pushed;
            }
        }
        return 0;
    }

    long long max_flow() {
        long long total=0;
        while(bfs()) {
            fill(ptr.begin(), ptr.end(), 0);
            while (long long pushed=augment(s, 1e18))
                total+=pushed;
        }
        return total;
    }
};

int main() {
    int n, t;
    cin>>n>>t;
    vector<string> sci(n), cap(n);
    for (int i=0; i<n; i++) cin>>sci[i];
    for (int i=0; i<n; i++) cin>>cap[i];

    int dis[15][15], dis2[15][15];

    auto valid = [&](int x, int y) {
