        queue<pii> q;
        q.push({x,y});
        memset(dis, -1, sizeof dis);
        dis[x][y]=0;
        while (!q.empty()) {
            auto u=q.front(); q.pop();
            for (int i=0; i<4; i++) {
                int vx=u.first+dx[i], vy=u.second+dy[i];
                if (valid(vx, vy) && dis[vx][vy]==-1) {
                    dis[vx][vy]=dis[u.first][u.second]+1;
                    q.push({vx, vy});
                }
            }
        }
        for (int i=0; i<n; i++) {
            for (int j=0; j<n; j++) {
                if (dis[i][j]==-1) dis[i][j]=1000000000;
            }
        }
    };

    int dp[65][12][12][12][12];
    memset(dp, -1, sizeof dp);

    auto reachable = [&](int tt, int x0, int y0, int x, int y) {
        if (dis[x0][y0]<tt) return 0;
        if (x0==x && y0==y) return 1;
        if (tt>=t) return 0;
        if (dis[x0][y0]<=tt) return 0;
        if (dp[tt][x0][y0][x][y]!=-1) return dp[tt][x0][y0][x][y];
        for (int j=0; j<4; j++) {
            int xx=x0+dx[j], yy=y0+dy[j];
            if (xx<0 || xx>=n || yy<0 || yy>=n) continue;
            if (sci[xx][yy]=='Y' || sci[xx][yy]=='Z') continue;
            if (reachable(tt+1, xx, yy, x, y))
                return dp[tt][x0][y0][x][y]=1;
        }
        return dp[tt][x0][y0][x][y]=0;
    };

    for (int i=0; i<n; i++) {
        for (int j=0; j<n; j++) {
            if (sci[i][j]=='Z') bfs1(i,j);
        }
    }

    vector<pii> sources, sinks;
    for (int i=0; i<n; i++) {
        for (int j=0; j<n; j++) {
