import java.util.*;
import java.io.*;

public class Main {
    static int[] dx = {1, -1, 0, 0};
    static int[] dy = {0, 0, 1, -1};
    static final int INF = 1000000000;

    static class Edge {
        int v, u;
        long cap, flow = 0;
        public Edge(int v, int u, long cap) {
            this.v = v;
            this.u = u;
            this.cap = cap;
        }
    }

    static class Network {
        List<Edge> edges = new ArrayList<>();
        List<List<Integer>> adj = new ArrayList<>();
        int n, m = 0, s, t;
        int[] level, ptr;
        Queue<Integer> q = new LinkedList<>();

        public Network(int n, int s, int t) {
            this.n = n;
            this.s = s;
            this.t = t;
            for (int i = 0; i < n; i++) {
                adj.add(new ArrayList<>());
            }
            level = new int[n];
            ptr = new int[n];
        }

        void add_edge(int v, int u, long cap) {
            edges.add(new Edge(v, u, cap));
            edges.add(new Edge(u, v, 0));
            adj.get(v).add(m);
            adj.get(u).add(m + 1);
            m += 2;
        }

        boolean bfs() {
            q.clear();
            Arrays.fill(level, -1);
            level[s] = 0;
            q.offer(s);
            while (!q.isEmpty()) {
                int v = q.poll();
                for (int id : adj.get(v)) {
                    Edge e = edges.get(id);
                    if (e.cap - e.flow < 1) continue;
                    if (level[e.u] != -1) continue;
                    level[e.u] = level[v] + 1;
                    q.offer(e.u);
                }
            }
            return level[t] != -1;
        }

        long augment(int v, long flow_in) {
            if (v == t) return flow_in;
            for (int& cid = ptr[v]; cid < adj.get(v).size(); cid++) {
                int id = adj.get(v).get(cid);
                Edge e = edges.get(id);
                int u = e.u;
                if (level[v] + 1 != level[u] || e.cap - e.flow < 1) continue;
                long pushed = augment(u, Math.min(flow_in, e.cap - e.flow));
                if (pushed > 0) {
                    edges.get(id).flow += pushed;
                    edges.get(id ^ 1).flow -= pushed;
                    return pushed;
                }
            }
            return 0;
        }

        long max_flow() {
            long total = 0;
            while (bfs()) {
                Arrays.fill(ptr, 0);
                long pushed;
                while ((pushed = augment(s, Long.MAX_VALUE)) > 0) {
                    total += pushed;
                }
            }
            return total;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int t = Integer.parseInt(st.nextToken());

        String[] sci = new String[n];
        String[] cap = new String[n];

        for (int i = 0; i < n; i++) {
            sci[i] = br.readLine();
        }
        for (int i = 0; i < n; i++) {
            cap[i] = br.readLine();
        }

        int[][] dis = new int[15][15];
        int[][] dis2 = new int[15][15];

        // Helper function to check validity
        class Utils {
            boolean valid(int x, int y) {
                if (x < 0 || y < 0 || x >= n || y >= n) return false;
                if (sci[x].charAt(y) == 'Y' || sci[x].charAt(y) == 'Z') return false;
                return true;
            }

            void bfs1(int x, int y) {
                for (int[] row : dis) Arrays.fill(row, -1);
                Queue<int[]> q = new LinkedList<>();
                q.offer(new int[]{x, y});
                dis[x][y] = 0;
                while (!q.isEmpty()) {
                    int[] u = q.poll();
                    for (int i = 0; i < 4; i++) {
                        int vx = u[0] + dx[i];
                        int vy = u[1] + dy[i];
                        if (valid(vx, vy) && dis[vx][vy] == -1) {
                            dis[vx][vy] = dis[u[0]][u[1]] + 1;
                            q.offer(new int[]{vx, vy});
                        }
                    }
                }
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < n; j++) {
                        if (dis[i][j] == -1) dis[i][j] = INF;
                    }
                }
            }

            boolean reachable(int tt, int x0, int y0, int x, int y, int[][] dis, String[] sci) {
                if (dis[x0][y0] < tt) return false;
                if (x0 == x && y0 == y) return true;
                if (tt >= t) return false;
                if (dis[x0][y0] <= tt) return false;
                if (dp[tt][x0][y0][x][y] != -1) return dp[tt][x0][y0][x][y] == 1;
                for (int j = 0; j < 4; j++) {
                    int xx = x0 + dx[j];
                    int yy = y0 + dy[j];
                    if (xx < 0 || xx >= n || yy < 0 || yy >= n) continue;
                    if (sci[xx].charAt(yy) == 'Y' || sci[xx].charAt(yy) == 'Z') continue;
                    if (reachable(tt + 1, xx, yy, x, y, dis, sci))
                        return dp[tt][x0][y0][x][y] = 1;
                }
                return dp[tt][x0][y0][x][y] = 0;
            }
        }

        Utils utils = new Utils();

        // Precompute BFS for 'Z' cells
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (sci[i].charAt(j) == 'Z') {
                    utils.bfs1(i, j);
                }
            }
        }

        List<int[]> sources = new ArrayList<>();
        List<int[]> sinks = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                char c = sci[i].charAt(j);
                if (c != 'Z' && c != 'Y' && c != '0') {
                    sources.add(new int[]{i, j});
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                char c = cap[i].charAt(j);
                if (c != 'Z' && c != 'Y' && c != '0') {
                    sinks.add(new int[]{i, j});
                }
            }
        }

        int total_nodes = sources.size() + sinks.size() + 2;
        Network net = new Network(total_nodes, 0, total_nodes - 1);

        for (int i = 0; i < sources.size(); i++) {
            long c = sci[sources.get(i)[0]].charAt(sources.get(i)[1]) - '0';
            net.add_edge(0, i + 1, c);
        }

        for (int i = 0; i < sinks.size(); i++) {
            long c = cap[sinks.get(i)[0]].charAt(sinks.get(i)[1]) - '0';
            net.add_edge(sources.size() + 1 + i, total_nodes - 1, c);
        }

        for (int i = 0; i < sources.size(); i++) {
            for (int j = 0; j < sinks.size(); j++) {
                int[] src = sources.get(i);
                int[] sink = sinks.get(j);
                if (utils.reachable(0, src[0], src[1], sink[0], sink[1], dis, sci))
                    net.add_edge(i + 1, sources.size() + 1 + j, 10000000);
            }
        }

        System.out.println(net.max_flow());
    }
}
